const r=getComputedStyle(document.documentElement);
const out={bc:r.getPropertyValue('--border-color'), bca:r.getPropertyValue('--border-color-alternative'), focus:r.getPropertyValue('--focus'), focusColor:r.getPropertyValue('--focus-color')};
const hits=[];
for (const ss of document.styleSheets){ let rules; try{rules=ss.cssRules}catch(e){continue}
 const walk=(rs)=>{for(const x of rs){ if(x.cssRules&&!x.selectorText) walk(x.cssRules); else if(x.selectorText && /br-radio input\s*\+\s*label:before|br-radio input\s*\+\s*label::before|br-checkbox input\s*\+\s*label:before|br-checkbox input\s*\+\s*label::before/.test(x.selectorText)) hits.push((ss.href||'').split('/').pop()+' | '+x.cssText.slice(0,300));}};
 walk(rules);
}
out.hits=hits; return out;
}"}

